const clean = (value) => {
  if (typeof value !== 'string') return null;
  const result = value.trim();
  return result.length > 0 ? result : null;
};

return $input.all().map((item) => {
  // Webhook input is wrapped in `body`. Direct test input may already be canonical.
  const raw = item.json.body ?? item.json;
  const customer = raw.customer ?? {};
  const message = raw.message ?? {};
  const metadata = raw.metadata ?? {};

  const email = clean(customer.email);

  return {
    json: {
      source: clean(raw.source)?.toLowerCase() ?? null,
      source_event_id: clean(raw.source_event_id),
      received_at: clean(raw.received_at),
      customer: {
        name: clean(customer.name),
        email: email?.toLowerCase() ?? null,
        phone: clean(customer.phone),
      },
      message: {
        subject: clean(message.subject),
        body: clean(message.body),
        channel: clean(message.channel)?.toLowerCase() ?? null,
      },
      metadata: {
        page_url: clean(metadata.page_url),
        utm_source: clean(metadata.utm_source)?.toLowerCase() ?? null,
        location_hint: clean(metadata.location_hint),
      },
    },
  };
});

const allowedSources = new Set([
  'website_form',
  'gmail',
  'manual_api',
  'phone_note',
  'partner_referral',
]);

const allowedChannels = new Set([
  'form',
  'email',
  'api',
  'phone_note',
  'referral',
]);

const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

return $input.all().map((item) => {
  const inquiry = item.json;
  const blockingIssues = [];
  const reviewIssues = [];

  const addBlocking = (field, code, message) => {
    blockingIssues.push({ field, code, message });
  };

  const addReview = (field, code, message) => {
    reviewIssues.push({ field, code, message });
  };

  if (!inquiry.source) {
    addBlocking('source', 'required', 'Source is required.');
  } else if (!allowedSources.has(inquiry.source)) {
    addBlocking('source', 'invalid_enum', 'Source is not supported.');
  }

  if (!inquiry.source_event_id) {
    addBlocking('source_event_id', 'required', 'Source event ID is required.');
  }

  if (!inquiry.received_at) {
    addBlocking('received_at', 'required', 'Received timestamp is required.');
  } else if (Number.isNaN(Date.parse(inquiry.received_at))) {
    addBlocking('received_at', 'invalid_datetime', 'Received timestamp must be a valid ISO date-time.');
  }

  if (!inquiry.message?.body) {
    addBlocking('message.body', 'required', 'Inquiry message body is required.');
  }

  if (!inquiry.message?.channel) {
    addBlocking('message.channel', 'required', 'Message channel is required.');
  } else if (!allowedChannels.has(inquiry.message.channel)) {
    addBlocking('message.channel', 'invalid_enum', 'Message channel is not supported.');
  }

  const email = inquiry.customer?.email;
  const phone = inquiry.customer?.phone;

  if (!email && !phone) {
    addReview(
      'customer',
      'missing_contact_method',
      'At least one of email or phone is required for automatic processing.'
    );
  }

  if (email && !emailPattern.test(email)) {
    addReview('customer.email', 'invalid_email', 'Email format is invalid.');
  }

  if (phone) {
    const phoneDigits = phone.replace(/\D/g, '');
    if (phoneDigits.length < 8 || phoneDigits.length > 15) {
      addReview('customer.phone', 'invalid_phone', 'Phone must contain 8 to 15 digits.');
    }
  }

  let disposition = 'accepted';

  if (blockingIssues.length > 0) {
    disposition = 'rejected';
  } else if (reviewIssues.length > 0) {
    disposition = 'manual_review';
  }

  return {
    json: {
      ...inquiry,
      validation: {
        is_valid: disposition === 'accepted',
        disposition,
        issues: [...blockingIssues, ...reviewIssues],
      },
    },
  };
});

