return $input.all().map((item) => {
  const inquiry = item.json;
  const source = inquiry.source;
  const sourceEventId = inquiry.source_event_id;
  const executionId = String($execution.id);
  const dedupKey = source && sourceEventId ? `${source}:${sourceEventId}` : null;
