return $input.all().map((item) => {
  const inquiry = item.json;

  return {
    json: {
      ...inquiry,
      ai: {
        ...inquiry.ai,
        request: {
          model: 'openai/gpt-oss-20b',
          messages: [
            { role: 'system', content: augmentedSystemPrompt },
            { role: 'user', content: JSON.stringify(inquiry.ai.input) },
          ],
          response_format: {
            type: 'json_schema',
            json_schema: {
              name: 'construction_inquiry_classification',
              strict: true,
              schema: strictSchema,
            },
          },
          reasoning_effort: 'low',
          max_completion_tokens: 1200,
        },
      },
    },
