});

const requestItems = $('Build Groq Request').all();

return $input.all().map((item, index) => {
  const original = requestItems[index]?.json;
  if (!original) {
    throw new Error(`Missing original inquiry for Groq response item ${index}`);
  }

  if (item.json.error) {
    const { request, ...aiWithoutRequest } = original.ai;
    const message = item.json.error.message ?? String(item.json.error);
    return {
      json: {
        ...original,
        ai: {
          ...aiWithoutRequest,
          status: 'failed',
          provider: 'groq',
          model: 'openai/gpt-oss-20b',
          result: null,
          error: {
            system: 'groq',
            operation: 'classify_inquiry',
            message,
            retry_exhausted: true,
          },
        },
      },
    };
  }

  const content = item.json.choices?.[0]?.message?.content;
  if (typeof content !== 'string' || content.length === 0) {
    const { request, ...aiWithoutRequest } = original.ai;
    return {
      json: {
        ...original,
        ai: {
          ...aiWithoutRequest,
          status: 'failed',
          provider: 'groq',
          model: item.json.model ?? 'openai/gpt-oss-20b',
          result: null,
          error: {
            system: 'groq',
            operation: 'parse_response',
            message: 'Groq response is missing choices[0].message.content',
            retry_exhausted: false,
          },
        },
      },
    };
  }

  let result;
  try {
    result = JSON.parse(content);
  } catch (error) {
    const { request, ...aiWithoutRequest } = original.ai;
    return {
      json: {
        ...original,
        ai: {
          ...aiWithoutRequest,
          status: 'failed',
          provider: 'groq',
          model: item.json.model ?? 'openai/gpt-oss-20b',
          result: null,
          error: {
            system: 'groq',
            operation: 'parse_response',
            message: `Groq returned invalid JSON: ${error.message}`,
            retry_exhausted: false,
          },
        },
      },
    };
  }

  const { request, ...aiWithoutRequest } = original.ai;

  return {
    json: {
      ...original,
      ai: {
        ...aiWithoutRequest,
        status: 'completed',
        provider: 'groq',
        model: item.json.model ?? 'openai/gpt-oss-20b',
        result,
        usage: item.json.usage ?? null,
      },
    },
  };
});

const allowed = {
  category: new Set([
    'emergency_repair',
    'remodel',
    'roofing',
    'commercial',
    'outdoor',
    'general_question',
  ]),
  propertyType: new Set(['residential', 'commercial', 'unknown']),
  timeline: new Set([
    'emergency',
    'within_7_days',
    'within_30_days',
    'within_90_days',
    'flexible',
    'unknown',
  ]),
  budgetRange: new Set(['under_5k', '5k_15k', '15k_50k', '50k_plus', 'unknown']),
  urgency: new Set(['emergency', 'time_sensitive', 'routine', 'unknown']),
  leadQuality: new Set(['qualified', 'needs_more_info', 'not_a_fit', 'spam']),
  missingField: new Set([
    'name',
    'email',
    'phone',
    'service_requested',
    'property_type',
    'location',
    'timeline',
    'budget',
  ]),
  signal: new Set([
    'safety_risk',
    'active_damage',
    'same_day_request',
    'short_timeline',
    'explicit_budget',
    'commercial_project',
    'detailed_scope',
    'vague_request',
    'spam_signal',
  ]),
};

const normalizeEmail = (value) =>
  typeof value === 'string' ? value.trim().toLowerCase() : null;
const normalizePhone = (value) =>
  typeof value === 'string' ? value.replace(/\D/g, '') : null;

return $input.all().map((item) => {
  const inquiry = item.json;
  const result = inquiry.ai?.result;
  const issues = [];
  const warnings = [];

  const issue = (code, path, message) => issues.push({ code, path, message });
  const warning = (code, path, message) => warnings.push({ code, path, message });

  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    issue('missing_result', 'ai.result', 'AI result must be an object.');
  } else {
    const resultLeadQuality = result.classification?.lead_quality;
    if (!allowed.category.has(result.project?.category)) {
      issue('invalid_enum', 'project.category', 'Unsupported project category.');
    }
    if (!['spam', 'not_a_fit'].includes(resultLeadQuality) &&
        (typeof result.project?.service_requested !== 'string' || !result.project.service_requested.trim())) {
      issue('required', 'project.service_requested', 'Service requested must be non-empty text.');
    }
    if (!allowed.propertyType.has(result.project?.property_type)) {
      issue('invalid_enum', 'project.property_type', 'Unsupported property type.');
    }
    if (!allowed.timeline.has(result.project?.timeline)) {
      issue('invalid_enum', 'project.timeline', 'Unsupported timeline.');
    }
    if (!allowed.budgetRange.has(result.project?.budget_range)) {
      issue('invalid_enum', 'project.budget_range', 'Unsupported budget range.');
    }
    const exactBudget = result.project?.exact_budget_amount;
    if (exactBudget !== null && (!Number.isFinite(exactBudget) || exactBudget < 0)) {
      issue('invalid_number', 'project.exact_budget_amount', 'Exact budget must be null or a non-negative number.');
    }
    if (!allowed.urgency.has(result.classification?.urgency)) {
      issue('invalid_enum', 'classification.urgency', 'Unsupported urgency.');
    }
    if (!allowed.leadQuality.has(result.classification?.lead_quality)) {
      issue('invalid_enum', 'classification.lead_quality', 'Unsupported lead quality.');
    }
    const confidence = result.classification?.confidence;
    if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) {
      issue('invalid_confidence', 'classification.confidence', 'Confidence must be between 0 and 1.');
    } else if (confidence < 0.75) {
      issue('low_confidence', 'classification.confidence', 'Confidence is below the 0.75 automation threshold.');
    }
    if (typeof result.summary !== 'string' || !result.summary.trim()) {
      issue('required', 'summary', 'Summary must be non-empty text.');
    }
    if (!Array.isArray(result.missing_fields) ||
        result.missing_fields.some((value) => !allowed.missingField.has(value))) {
      issue('invalid_array', 'missing_fields', 'Missing fields contain an unsupported value.');
    }
    if (!Array.isArray(result.signals) ||
        result.signals.some((value) => !allowed.signal.has(value))) {
      issue('invalid_array', 'signals', 'Signals contain an unsupported value.');
    }

    const canonicalEmail = normalizeEmail(inquiry.customer?.email);
    const extractedEmail = normalizeEmail(result.extracted_contact?.email);
    if (canonicalEmail && extractedEmail && canonicalEmail !== extractedEmail) {
      warning('contact_conflict', 'extracted_contact.email', 'Extracted email differs from canonical email; canonical value wins.');
    }

    const canonicalPhone = normalizePhone(inquiry.customer?.phone);
    const extractedPhone = normalizePhone(result.extracted_contact?.phone);
    if (canonicalPhone && extractedPhone && canonicalPhone !== extractedPhone) {
      warning('contact_conflict', 'extracted_contact.phone', 'Extracted phone differs from canonical phone; canonical value wins.');
    }
  }

  const schemaValid = issues.every((entry) => entry.code !== 'missing_result' && entry.code !== 'invalid_enum' && entry.code !== 'invalid_number' && entry.code !== 'invalid_confidence' && entry.code !== 'invalid_array' && entry.code !== 'required');
  const confidenceAcceptable = !issues.some((entry) => entry.code === 'low_confidence' || entry.code === 'invalid_confidence');
  const leadQuality = result?.classification?.lead_quality;

  let disposition = 'continue';
  if (!schemaValid || !confidenceAcceptable) disposition = 'manual_review';
  if (leadQuality === 'spam' || leadQuality === 'not_a_fit') disposition = 'stop_no_crm';

  return {
    json: {
      ...inquiry,
      ai: {
        ...inquiry.ai,
        validation: {
          is_valid: issues.length === 0,
          schema_valid: schemaValid,
          confidence_acceptable: confidenceAcceptable,
          disposition,
          issues,
          warnings,
        },
      },
    },
  };
});

const pipelineId = 'default';
const newInquiryStageId = 'appointmentscheduled';

const budgetRangeFor = (amount) => {
  if (!Number.isFinite(amount)) return null;
  if (amount < 5000) return 'under_5k';
  if (amount < 15000) return '5k_15k';
  if (amount < 50000) return '15k_50k';
  return '50k_plus';
};

return $input.all().map((item) => {
  const inquiry = item.json;
  const result = inquiry.ai.result;
  const validation = inquiry.ai.validation;
  const project = result.project;
  const classification = result.classification;
  const signals = new Set(result.signals);

  const emergency =
    classification.urgency === 'emergency' ||
    project.timeline === 'emergency' ||
    signals.has('safety_risk') ||
    signals.has('active_damage') ||
    signals.has('same_day_request');

  const highValue =
    Number.isFinite(project.exact_budget_amount) &&
    project.exact_budget_amount >= 50000;

  const timeSensitive =
    classification.urgency === 'time_sensitive' ||
    project.timeline === 'within_7_days' ||
    project.timeline === 'within_30_days' ||
    signals.has('short_timeline');

  let priority = 'normal';
  if (emergency) priority = 'urgent';
  else if (highValue || timeSensitive || project.category === 'commercial') priority = 'high';
  else if (classification.lead_quality === 'needs_more_info' || signals.has('vague_request')) priority = 'low';

  let assignedRole = 'office_coordinator';
  if (emergency || project.category === 'commercial') assignedRole = 'owner';
  else if (['roofing', 'remodel'].includes(project.category)) assignedRole = 'estimator';
  else if (project.category === 'outdoor') assignedRole = 'project_manager';

  let nextAction = 'schedule_site_visit';
  if (emergency) nextAction = 'call_now';
  else if (classification.lead_quality === 'needs_more_info' || result.missing_fields.length > 0) {
    nextAction = 'request_missing_info';
  } else if (project.category === 'general_question') {
    nextAction = 'send_estimate_request';
  }

  let acknowledgmentType = 'standard';
  if (emergency) acknowledgmentType = 'urgent';
  else if (nextAction === 'request_missing_info') acknowledgmentType = 'missing_info';

  const crmAllowed =
    validation.disposition === 'continue' &&
    validation.is_valid &&
    !['spam', 'not_a_fit'].includes(classification.lead_quality);

  const canonical = inquiry.customer ?? {};
  const extracted = result.extracted_contact ?? {};
  const finalContact = {
    name: canonical.name ?? extracted.name ?? null,
    email: canonical.email ?? extracted.email ?? null,
    phone: canonical.phone ?? extracted.phone ?? null,
    city: project.city,
    state: project.state,
  };

  const exactBudget = Number.isFinite(project.exact_budget_amount)
    ? project.exact_budget_amount
