const safeError = (value) => {
  if (!value) return null;
  if (typeof value === 'string') return value;
  return value.message ?? JSON.stringify(value);
};

return $input.all().map((item) => {
  const inquiry = item.json;
  const validationDisposition = inquiry.validation?.disposition;
  const aiDisposition = inquiry.ai?.validation?.disposition;
  const contactStatus = inquiry.hubspot?.contact?.search_status;
  const dealStatus = inquiry.hubspot?.deal?.search_status;
  const integrationError = inquiry.hubspot?.error ?? inquiry.ai?.error ?? null;

  let automationStatus = 'manual_review';
  let responseStatus = 'manual_review';
  let responseCode = 202;
  let message = 'Inquiry was saved for manual review.';

  if (inquiry.hubspot?.status === 'crm_synced') {
    automationStatus = 'completed';
    responseStatus = 'accepted';
    message = 'Inquiry was classified and synchronized to HubSpot.';
  } else if (dealStatus === 'found') {
    automationStatus = 'completed_existing_deal';
    responseStatus = 'accepted';
    message = 'The existing HubSpot Deal was reused; no duplicate Deal was created.';
  } else if (aiDisposition === 'stop_no_crm') {
    automationStatus = 'stopped_no_crm';
    responseStatus = 'filtered';
    responseCode = 200;
    message = 'Inquiry was classified as spam or not a fit; CRM creation was skipped.';
  } else if (integrationError) {
    automationStatus = 'integration_error';
    responseStatus = 'manual_review';
    message = 'Inquiry was saved, but an external service failed after retries; manual follow-up is required.';
  } else if (contactStatus === 'multiple_matches') {
    automationStatus = 'contact_match_review';
    message = 'Multiple Contacts matched; no CRM write was attempted.';
  } else if (dealStatus === 'multiple_matches') {
    automationStatus = 'deal_match_review';
    message = 'Multiple Deals matched; no Deal was created.';
  } else if (validationDisposition === 'manual_review') {
    automationStatus = 'intake_manual_review';
    message = 'Inquiry was saved because its contact information needs review.';
  } else if (aiDisposition === 'manual_review') {
    automationStatus = inquiry.ai?.status === 'failed' ? 'ai_error' : 'ai_manual_review';
    message = inquiry.ai?.status === 'failed'
      ? 'AI classification failed after retries; the inquiry was saved for manual review.'
      : 'AI confidence or schema validation requires manual review.';
  }

  const completedAt = new Date().toISOString();
  const errorMessage = safeError(integrationError);
  const response = {
    status: responseStatus,
    inquiry_id: inquiry.identity?.inquiry_id ?? null,
    source_event_id: inquiry.source_event_id ?? null,
    automation_status: automationStatus,
    hubspot_contact_id: inquiry.hubspot?.contact?.contact_id ?? null,
    hubspot_deal_id: inquiry.hubspot?.deal?.deal_id ?? null,
    message,
  };

  return {
    json: {
      ...inquiry,
      finalization: {
        automation_status: automationStatus,
        ai_status: inquiry.ai?.status ?? 'not_run',
        ai_result_json: JSON.stringify(inquiry.ai?.result ?? null),
        hubspot_contact_id: response.hubspot_contact_id,
        hubspot_deal_id: response.hubspot_deal_id,
        last_error: errorMessage,
        completed_at: completedAt,
        result_json: JSON.stringify({
          automation_status: automationStatus,
          ai: inquiry.ai ?? null,
          business: inquiry.business ?? null,
          hubspot: inquiry.hubspot ?? null,
        }),
        response_code: responseCode,
        response,
      },
    },
  };
});

