return $input.all().map((item) => ({ json: {
  ...item.json,
  communication: { ...item.json.communication, followup: {
    ...item.json.communication.followup,
    status: 'failed',
  } },
} }));

return $input.all().map((item) => {
  const inquiry = item.json;
  const errors = [
    inquiry.communication?.email?.error,
    inquiry.communication?.slack?.error,
    inquiry.communication?.followup?.error,
  ].filter(Boolean);
  return { json: { ...inquiry, followup_persistence: {
    followup_status: inquiry.communication.followup.status,
    followup_due_at: inquiry.communication.followup.due_at ?? '',
    followup_sent_at: inquiry.communication.followup.sent_at ?? '',
    communication_last_error: errors.join(' | '),
    communication_result_json: JSON.stringify(inquiry.communication),
  } } };
});

return $input.all().map((item) => {
  const inquiry = item.json;
  const finishedAt = new Date().toISOString();
  const startedAt = inquiry.operations?.processing_started_at ?? finishedAt;
  const duration = Math.max(0, Date.parse(finishedAt) - Date.parse(startedAt));
  const status = inquiry.finalization?.automation_status ?? 'unknown';
  const error = inquiry.hubspot?.error ?? inquiry.ai?.error ?? null;

  let processingStage = 'core_processing_completed';
  let lastSuccessfulStage = 'final_outcome_prepared';
  if (status === 'stopped_no_crm') processingStage = 'filtered_no_crm';
  if (status.includes('manual_review')) processingStage = 'manual_review';
  if (['integration_error', 'ai_error'].includes(status)) processingStage = 'external_failure_handled';

  return {
    json: {
      ...inquiry,
      operations: {
        ...inquiry.operations,
        processing_stage: processingStage,
        processing_finished_at: finishedAt,
        processing_duration_ms: duration,
        last_successful_stage: lastSuccessfulStage,
        error_stage: error?.operation ?? null,
        error_category: error ? 'external_service' : null,
      },
    },
  };
});
